// The npm backend (docs/spec/fsm.md, B-4 and B-6; docs/plans/fsm-v1.md, C-2): the generated files of the npm package
// `src/` and the native vector module `tests/vectors.mjs`. It takes the IRs of the machines (normalize.mjs), in definition
// order, and the lock, and returns the text of every file; it writes nothing. The output is deterministic: declaration order,
// two spaces of indentation and a final line break. The core imports nothing from node:, and the generated code has no runtime
// dependency.

import { forKind } from '../core/vectors.mjs';

const SHARED = 'fsm';
const KIND = 'npm';

/** The member name of a key: the pascal notation of B-6. Keys match ^[a-z][a-z0-9]*(_[a-z][a-z0-9]*)*$, so this is one-to-one. */
const pascal = key => key.split('_').map(word => word[0].toUpperCase() + word.slice(1)).join('');

/** The first line of a generated file (docs/spec/fsm.md, B-6). */
const header = from => `// Code generated by fsm-gen from ${from}; DO NOT EDIT.`;

/** The text of a list of lines: each line ends with a line break. */
const text = lines => `${lines.join('\n')}\n`;

/** The shared module: the error codes of B-4, B-5 and B-6 that the functions throw, and the Error class of every machine. */
const FSM_JS = text([
  header(SHARED),
  '',
  '/** The error codes that the functions of every machine throw (docs/spec/fsm.md, B-4 and B-6). */',
  'export const Code = Object.freeze({',
  "  Conflict: 'E_CONFLICT',",
  "  InvalidTransition: 'E_INVALID_TRANSITION',",
  "  UnknownCode: 'E_UNKNOWN_CODE',",
  "  ReservedCode: 'E_RESERVED_CODE',",
  '});',
  '',
  '/** The error of a machine function. The fields hold the arguments of apply or target that failed; the others are undefined. */',
  'export class Error extends globalThis.Error {',
  '  constructor(code, message, { expected, actual, event } = {}) {',
  '    super(message);',
  '    this.code = code;',
  '    this.expected = expected;',
  '    this.actual = actual;',
  '    this.event = event;',
  '  }',
  '}',
]);

const FSM_DTS = text([
  header(SHARED),
  '',
  '/** The error codes that the functions of every machine throw (docs/spec/fsm.md, B-4 and B-6). */',
  'export declare const Code: {',
  "  readonly Conflict: 'E_CONFLICT';",
  "  readonly InvalidTransition: 'E_INVALID_TRANSITION';",
  "  readonly UnknownCode: 'E_UNKNOWN_CODE';",
  "  readonly ReservedCode: 'E_RESERVED_CODE';",
  '};',
  "export type ErrorCode = 'E_CONFLICT' | 'E_INVALID_TRANSITION' | 'E_UNKNOWN_CODE' | 'E_RESERVED_CODE';",
  '',
  '/** The error of a machine function. The fields hold the arguments of apply or target that failed; the others are undefined. */',
  'export declare class Error extends globalThis.Error {',
  '  constructor(code: ErrorCode, message: string, fields?: { readonly expected?: number; readonly actual?: number; readonly event?: number });',
  '  readonly code: ErrorCode;',
  '  readonly expected: number | undefined;',
  '  readonly actual: number | undefined;',
  '  readonly event: number | undefined;',
  '}',
]);

/** The machine module of `ir` with its reserved codes from `lock`: the states, events and functions of B-6, in that order. */
function machineJs(ir, lock) {
  const { machine, initial, states, events, transitions } = ir;
  const reserved = [...lock[machine].reserved].sort((a, b) => a - b);
  const stateOf = key => `State.${pascal(key)}`;
  const eventOf = key => `Event.${pascal(key)}`;
  const outgoing = state => events.filter(event => transitions.some(item => item.state === state.key && item.event === event.key));
  const toOf = (state, event) => transitions.find(item => item.state === state && item.event === event).to;
  const lines = [
    header(machine),
    "import { Code, Error } from './fsm.js';",
    '',
    `/** The states of ${machine}: the value of each member is its code. */`,
    'export const State = Object.freeze({',
    ...states.map(state => `  ${pascal(state.key)}: ${state.code},`),
    '});',
    '',
    `/** The events of ${machine}: the value of each member is its position in the declaration, from 1. */`,
    'export const Event = Object.freeze({',
    ...events.map((event, index) => `  ${pascal(event.key)}: ${index + 1},`),
    '});',
    '',
    '/** The error of a state value that is no state of the machine. */',
    'function unknownState(value) {',
    `  return new Error(Code.UnknownCode, '${machine}: ' + String(value) + ' is not a state of ${machine}');`,
    '}',
    '',
    '/** The error of an event that has no edge from the state. */',
    'function invalidTransition(expected, event) {',
    `  return new Error(Code.InvalidTransition, '${machine}: the event ' + String(event) + ' has no edge from ' + String(expected), { expected, event });`,
    '}',
    '',
    `/** The initial state of ${machine}. */`,
    'export function initial() {',
    `  return ${stateOf(initial)};`,
    '}',
    '',
    '/** The code of a state, which is its value; E_UNKNOWN_CODE for a value that is no state. */',
    'export function code(state) {',
    '  switch (state) {',
    ...states.map(state => `    case ${stateOf(state.key)}: return ${state.code};`),
    '    default: throw unknownState(state);',
    '  }',
    '}',
    '',
    '/** The key of a state. */',
    'export function key(state) {',
    '  switch (state) {',
    ...states.map(state => `    case ${stateOf(state.key)}: return '${state.key}';`),
    '    default: throw unknownState(state);',
    '  }',
    '}',
    '',
    '/** The state of a code: E_RESERVED_CODE for a reserved code, E_UNKNOWN_CODE for any other value. */',
    'export function fromCode(value) {',
    '  switch (value) {',
    ...states.map(state => `    case ${state.code}: return ${stateOf(state.key)};`),
    ...reserved.map(item => `    case ${item}: throw new Error(Code.ReservedCode, '${machine}: code ${item} is reserved and is no state of ${machine}');`),
    '    default: throw unknownState(value);',
    '  }',
    '}',
    '',
    '/** Whether a state is final. */',
    'export function isFinal(state) {',
    '  switch (state) {',
    ...states.map(state => `    case ${stateOf(state.key)}: return ${state.final};`),
    '    default: throw unknownState(state);',
    '  }',
    '}',
    '',
    '/** The events that have an edge from a state, in declaration order. */',
    'export function eventsFrom(state) {',
    '  switch (state) {',
    ...states.map(state => {
      const list = outgoing(state).map(event => eventOf(event.key));
      return `    case ${stateOf(state.key)}: return [${list.join(', ')}];`;
    }),
    '    default: throw unknownState(state);',
    '  }',
    '}',
    '',
    '/** The state that an event leads to from the expected state; E_INVALID_TRANSITION when the event has no edge from it. */',
    'export function target(expected, event) {',
    '  switch (expected) {',
    ...states.flatMap(state => {
      const edges = outgoing(state);
      if (edges.length === 0) return [`    case ${stateOf(state.key)}: throw invalidTransition(expected, event);`];
      return [
        `    case ${stateOf(state.key)}:`,
        '      switch (event) {',
        ...edges.map(edge => `        case ${eventOf(edge.key)}: return ${stateOf(toOf(state.key, edge.key))};`),
        '        default: throw invalidTransition(expected, event);',
        '      }',
      ];
    }),
    '    default: throw unknownState(expected);',
    '  }',
    '}',
    '',
    '/** Applies an event that the observed state expected leads to, when the stored state is actual (docs/spec/fsm.md, B-4). */',
    'export function apply(expected, event, actual) {',
    '  const to = target(expected, event);',
    '  code(actual);',
    '  if (actual === expected) return { to, changed: true };',
    '  if (actual === to) return { to, changed: false };',
    `  throw new Error(Code.Conflict, '${machine}: the stored state ' + String(actual) + ' is neither ' + String(expected) + ' nor ' + String(to), { expected, actual, event });`,
    '}',
  ];
  return text(lines);
}

/** The declaration file of `ir`: the same names with the state and event types as unions. */
function machineDts(ir) {
  const { machine, states, events } = ir;
  const union = items => (items.length === 0 ? 'never' : items.join(' | '));
  const stateType = union(states.map(state => `${state.code}`));
  const eventType = union(events.map((event, index) => `${index + 1}`));
  return text([
    header(machine),
    `/** The states of ${machine}: the value of each member is its code. */`,
    'export declare const State: {',
    ...states.map(state => `  readonly ${pascal(state.key)}: ${state.code};`),
    '};',
    `export type State = ${stateType};`,
    '',
    `/** The events of ${machine}: the value of each member is its position in the declaration, from 1. */`,
    'export declare const Event: {',
    ...events.map((event, index) => `  readonly ${pascal(event.key)}: ${index + 1};`),
    '};',
    `export type Event = ${eventType};`,
    '',
    '/** The result of apply: the state that the event leads to, and whether the stored state changed. */',
    'export interface Step {',
    '  readonly to: State;',
    '  readonly changed: boolean;',
    '}',
    '',
    '/** The initial state of the machine. */',
    'export declare function initial(): State;',
    '/** The code of a state, which is its value. */',
    'export declare function code(state: State): number;',
    '/** The key of a state. */',
    `export declare function key(state: State): ${union(states.map(state => `'${state.key}'`))};`,
    '/** The state of a code. */',
    'export declare function fromCode(value: number): State;',
    '/** Whether a state is final. */',
    'export declare function isFinal(state: State): boolean;',
    '/** The events that have an edge from a state, in declaration order. */',
    'export declare function eventsFrom(state: State): Event[];',
    '/** The state that an event leads to from the expected state. */',
    'export declare function target(expected: State, event: Event): State;',
    '/** Applies an event that the observed state expected leads to, when the stored state is actual. */',
    'export declare function apply(expected: State, event: Event, actual: State): Step;',
  ]);
}

/** The file that exports every machine as its namespace, and the shared module. */
function indexJs(irs) {
  return text([
    header(SHARED),
    ...irs.map(ir => `export * as ${ir.machine} from './${ir.machine}.js';`),
    "export * as fsm from './fsm.js';",
  ]);
}

/**
 * The files of the npm package `src/` for the machines `irs` (their IRs in definition order) and the lock: `<machine>.js` and
 * `<machine>.d.ts` per machine, then `fsm.js`, `fsm.d.ts`, `index.js` and `index.d.ts`. Each file is { path, content }.
 */
export function files(irs, lock) {
  const out = [];
  for (const ir of irs) {
    if (!Object.hasOwn(lock, ir.machine)) throw new Error(`npm: the lock has no entry for machine ${ir.machine}`);
    out.push({ path: `${ir.machine}.js`, content: machineJs(ir, lock) });
    out.push({ path: `${ir.machine}.d.ts`, content: machineDts(ir) });
  }
  out.push({ path: 'fsm.js', content: FSM_JS });
  out.push({ path: 'fsm.d.ts', content: FSM_DTS });
  out.push({ path: 'index.js', content: indexJs(irs) });
  out.push({ path: 'index.d.ts', content: indexJs(irs) });
  return out;
}

/**
 * The native data module tests/vectors.mjs of `vectorList`, the vectors of every machine in order: `export const vectors = [...]`.
 * The cases of the npm kind (forKind) are written with their integers as numbers: a decimal string of the oracle becomes the
 * number nearest to it, which is an unsafe integer above 2^53, so from_code classes it as E_UNKNOWN_CODE (docs/spec/fsm.md, B-6).
 */
export function vectorsFile(list) {
  const vectorList = forKind(list, KIND).map(({ machine, cases }) => ({
    machine,
    cases: cases.map(({ input_type: inputType, ...entry }) => {
      // A typed input is given to npm only as a float: npm's number holds no string and no bool (TYPED_KINDS, docs/spec/fsm.md, B-6).
      if (inputType !== undefined && inputType !== 'float') throw new Error(`npm: the input type ${JSON.stringify(inputType)} of ${entry.id} is not a number`);
      return typeof entry.input === 'string' ? { ...entry, input: Number(entry.input) } : entry;
    }),
  }));
  return text([header(SHARED), '', `export const vectors = ${JSON.stringify(vectorList, null, 2)};`]);
}
